import axios from "axios";

const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

const api = axios.create({ baseURL: BASE_URL });

// Attach JWT to every request if present
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Auto-logout on 401
api.interceptors.response.use(
  (res) => res,
  (err) => {
    if (err.response?.status === 401) {
      localStorage.removeItem("token");
      localStorage.removeItem("user");
      window.location.href = "/";
    }
    return Promise.reject(err);
  }
);

// ── Auth ──────────────────────────────────────────────────────────────────────
export const authAPI = {
  signup: (data) => api.post("/auth/signup", data),
  login: (data) => api.post("/auth/login", data),
  me: () => api.get("/auth/me"),
};

// ── Dashboard ─────────────────────────────────────────────────────────────────
export const dashboardAPI = {
  get: () => api.get("/dashboard"),
};

// ── Prediction ────────────────────────────────────────────────────────────────
export const predictionAPI = {
  submit: (data) => api.post("/predict", data),
  history: (limit = 0) => api.get(`/predict/history${limit ? `?limit=${limit}` : ""}`),
};

// ── Doctors ───────────────────────────────────────────────────────────────────
export const doctorAPI = {
  list: (params) => api.get("/doctors", { params }),
  toggleAvailability: (data) => api.patch("/doctors/availability", data),
  patients: () => api.get("/doctors/patients"),
};

// ── Hospitals ─────────────────────────────────────────────────────────────────
export const hospitalAPI = {
  nearby: (lat, lon) => api.get("/hospitals", { params: { lat, lon } }),
};

export default api;
